package com.example.todolist;

import android.content.ContentValues;
import android.content.Context;
import android.database.Cursor;
import android.database.sqlite.SQLiteDatabase;
import android.database.sqlite.SQLiteOpenHelper;
import java.util.ArrayList;

public class TaskDatabaseHelper extends SQLiteOpenHelper {

    private static final String DATABASE_NAME = "todo_database.db";
    private static final int DATABASE_VERSION = 1;

    public static final String TABLE_TASKS = "tasks";

    public static final String COL_ID = "id";
    public static final String COL_TITLE = "title";
    public static final String COL_DESCRIPTION = "description";
    public static final String COL_DUE_TIME = "due_time";
    public static final String COL_COMPLETED = "completed";
    public static final String COL_CREATED_AT = "created_at";

    public TaskDatabaseHelper(Context context) {
        super(context, DATABASE_NAME, null, DATABASE_VERSION);
    }

    @Override
    public void onCreate(SQLiteDatabase db) {
        String createTable =
                "CREATE TABLE " + TABLE_TASKS + " (" +
                        COL_ID + " INTEGER PRIMARY KEY AUTOINCREMENT, " +
                        COL_TITLE + " TEXT NOT NULL, " +
                        COL_DESCRIPTION + " TEXT, " +
                        COL_DUE_TIME + " INTEGER DEFAULT 0, " +
                        COL_COMPLETED + " INTEGER DEFAULT 0, " +
                        COL_CREATED_AT + " INTEGER DEFAULT 0" +
                        ")";

        db.execSQL(createTable);
    }

    @Override
    public void onUpgrade(SQLiteDatabase db, int oldVersion, int newVersion) {
        db.execSQL("DROP TABLE IF EXISTS " + TABLE_TASKS);
        onCreate(db);
    }

    public long insertTask(Task task) {
        SQLiteDatabase db = getWritableDatabase();

        ContentValues values = new ContentValues();
        values.put(COL_TITLE, task.title);
        values.put(COL_DESCRIPTION, task.description);
        values.put(COL_DUE_TIME, task.dueTime);
        values.put(COL_COMPLETED, task.completed ? 1 : 0);
        values.put(COL_CREATED_AT, System.currentTimeMillis());

        long id = db.insert(TABLE_TASKS, null, values);
        task.id = (int) id;

        return id;
    }

    public int updateTask(Task task) {
        SQLiteDatabase db = getWritableDatabase();

        ContentValues values = new ContentValues();
        values.put(COL_TITLE, task.title);
        values.put(COL_DESCRIPTION, task.description);
        values.put(COL_DUE_TIME, task.dueTime);
        values.put(COL_COMPLETED, task.completed ? 1 : 0);

        return db.update(
                TABLE_TASKS,
                values,
                COL_ID + "=?",
                new String[]{String.valueOf(task.id)}
        );
    }

    public int deleteTask(int taskId) {
        SQLiteDatabase db = getWritableDatabase();

        return db.delete(
                TABLE_TASKS,
                COL_ID + "=?",
                new String[]{String.valueOf(taskId)}
        );
    }

    public Task getTask(int taskId) {
        SQLiteDatabase db = getReadableDatabase();

        Cursor cursor = db.query(
                TABLE_TASKS,
                null,
                COL_ID + "=?",
                new String[]{String.valueOf(taskId)},
                null,
                null,
                null
        );

        Task task = null;

        if (cursor.moveToFirst()) {
            task = taskFromCursor(cursor);
        }

        cursor.close();
        return task;
    }

    public ArrayList<Task> getAllTasks() {
        ArrayList<Task> tasks = new ArrayList<>();
        SQLiteDatabase db = getReadableDatabase();

        String sql =
                "SELECT * FROM " + TABLE_TASKS +
                        " ORDER BY " +
                        COL_COMPLETED + " ASC, " +
                        "CASE WHEN " + COL_DUE_TIME + " = 0 THEN 1 ELSE 0 END ASC, " +
                        COL_DUE_TIME + " ASC, " +
                        COL_CREATED_AT + " DESC";

        Cursor cursor = db.rawQuery(sql, null);

        while (cursor.moveToNext()) {
            tasks.add(taskFromCursor(cursor));
        }

        cursor.close();
        return tasks;
    }

    public ArrayList<Task> getPendingTasksWithReminder() {
        ArrayList<Task> tasks = new ArrayList<>();
        SQLiteDatabase db = getReadableDatabase();

        long now = System.currentTimeMillis();

        Cursor cursor = db.query(
                TABLE_TASKS,
                null,
                COL_COMPLETED + "=0 AND " + COL_DUE_TIME + ">?",
                new String[]{String.valueOf(now)},
                null,
                null,
                COL_DUE_TIME + " ASC"
        );

        while (cursor.moveToNext()) {
            tasks.add(taskFromCursor(cursor));
        }

        cursor.close();
        return tasks;
    }

    private Task taskFromCursor(Cursor cursor) {
        int id = cursor.getInt(cursor.getColumnIndexOrThrow(COL_ID));
        String title = cursor.getString(cursor.getColumnIndexOrThrow(COL_TITLE));
        String description = cursor.getString(cursor.getColumnIndexOrThrow(COL_DESCRIPTION));
        long dueTime = cursor.getLong(cursor.getColumnIndexOrThrow(COL_DUE_TIME));
        boolean completed = cursor.getInt(cursor.getColumnIndexOrThrow(COL_COMPLETED)) == 1;
        long createdAt = cursor.getLong(cursor.getColumnIndexOrThrow(COL_CREATED_AT));

        return new Task(id, title, description, dueTime, completed, createdAt);
    }
}
