package com.example.todolist;

import android.app.AlarmManager;
import android.app.PendingIntent;
import android.content.Context;
import android.content.Intent;
import java.util.ArrayList;

public class AlarmScheduler {

    public static void schedule(Context context, Task task) {
        if (task == null) return;

        if (task.completed || task.dueTime <= System.currentTimeMillis()) {
            cancel(context, task.id);
            return;
        }

        AlarmManager alarmManager = (AlarmManager) context.getSystemService(Context.ALARM_SERVICE);

        Intent intent = new Intent(context, ReminderReceiver.class);
        intent.putExtra("task_id", task.id);

        PendingIntent pendingIntent = PendingIntent.getBroadcast(
                context,
                task.id,
                intent,
                PendingIntent.FLAG_UPDATE_CURRENT | PendingIntent.FLAG_IMMUTABLE
        );

        if (alarmManager != null) {
            alarmManager.set(
                    AlarmManager.RTC_WAKEUP,
                    task.dueTime,
                    pendingIntent
            );
        }
    }

    public static void cancel(Context context, int taskId) {
        AlarmManager alarmManager = (AlarmManager) context.getSystemService(Context.ALARM_SERVICE);

        Intent intent = new Intent(context, ReminderReceiver.class);

        PendingIntent pendingIntent = PendingIntent.getBroadcast(
                context,
                taskId,
                intent,
                PendingIntent.FLAG_UPDATE_CURRENT | PendingIntent.FLAG_IMMUTABLE
        );

        if (alarmManager != null) {
            alarmManager.cancel(pendingIntent);
        }
    }

    public static void scheduleAll(Context context) {
        TaskDatabaseHelper db = new TaskDatabaseHelper(context);
        ArrayList<Task> tasks = db.getPendingTasksWithReminder();

        for (Task task : tasks) {
            schedule(context, task);
        }
    }
}
