package com.example.todolist;

import android.content.Context;
import android.graphics.Paint;
import android.view.Gravity;
import android.view.View;
import android.view.ViewGroup;
import android.widget.BaseAdapter;
import android.widget.CheckBox;
import android.widget.LinearLayout;
import android.widget.TextView;
import java.text.SimpleDateFormat;
import java.util.ArrayList;
import java.util.Date;
import java.util.Locale;

public class TaskAdapter extends BaseAdapter {

    public interface OnTaskCheckedChangeListener {
        void onChanged(Task task, boolean checked);
    }

    private final Context context;
    private ArrayList<Task> tasks;
    private final OnTaskCheckedChangeListener listener;
    private final SimpleDateFormat dateFormat =
            new SimpleDateFormat("dd MMM yyyy, hh:mm a", Locale.getDefault());

    public TaskAdapter(Context context, ArrayList<Task> tasks, OnTaskCheckedChangeListener listener) {
        this.context = context;
        this.tasks = tasks;
        this.listener = listener;
    }

    public void updateData(ArrayList<Task> newTasks) {
        this.tasks = newTasks;
        notifyDataSetChanged();
    }

    @Override
    public int getCount() {
        return tasks.size();
    }

    @Override
    public Task getItem(int position) {
        return tasks.get(position);
    }

    @Override
    public long getItemId(int position) {
        return tasks.get(position).id;
    }

    @Override
    public View getView(int position, View convertView, ViewGroup parent) {
        Task task = getItem(position);

        LinearLayout row = new LinearLayout(context);
        row.setOrientation(LinearLayout.HORIZONTAL);
        row.setPadding(dp(12), dp(10), dp(12), dp(10));
        row.setGravity(Gravity.CENTER_VERTICAL);

        CheckBox checkBox = new CheckBox(context);
        checkBox.setFocusable(false);
        checkBox.setFocusableInTouchMode(false);
        checkBox.setChecked(task.completed);

        LinearLayout textContainer = new LinearLayout(context);
        textContainer.setOrientation(LinearLayout.VERTICAL);
        textContainer.setPadding(dp(8), 0, 0, 0);

        LinearLayout.LayoutParams textParams =
                new LinearLayout.LayoutParams(
                        ViewGroup.LayoutParams.MATCH_PARENT,
                        ViewGroup.LayoutParams.WRAP_CONTENT
                );

        TextView titleText = new TextView(context);
        titleText.setText(task.title);
        titleText.setTextSize(18);
        titleText.setTextColor(0xFF222222);

        if (task.completed) {
            titleText.setPaintFlags(titleText.getPaintFlags() | Paint.STRIKE_THRU_TEXT_FLAG);
            titleText.setTextColor(0xFF888888);
        }

        TextView descriptionText = new TextView(context);

        if (task.description == null || task.description.trim().isEmpty()) {
            descriptionText.setVisibility(View.GONE);
        } else {
            descriptionText.setText(task.description);
            descriptionText.setTextSize(14);
            descriptionText.setTextColor(0xFF555555);
        }

        TextView dueText = new TextView(context);
        dueText.setTextSize(13);

        if (task.dueTime > 0) {
            dueText.setText("Reminder: " + dateFormat.format(new Date(task.dueTime)));
            dueText.setTextColor(0xFF1976D2);
        } else {
            dueText.setText("No reminder");
            dueText.setTextColor(0xFF999999);
        }

        textContainer.addView(titleText, textParams);
        textContainer.addView(descriptionText, textParams);
        textContainer.addView(dueText, textParams);

        row.addView(checkBox);
        row.addView(
                textContainer,
                new LinearLayout.LayoutParams(
                        0,
                        ViewGroup.LayoutParams.WRAP_CONTENT,
                        1
                )
        );

        checkBox.setOnCheckedChangeListener((buttonView, isChecked) -> {
            if (listener != null) {
                listener.onChanged(task, isChecked);
            }
        });

        return row;
    }

    private int dp(int value) {
        return (int) (value * context.getResources().getDisplayMetrics().density);
    }
}
