package com.example.todolist;

import android.Manifest;
import android.app.AlertDialog;
import android.app.DatePickerDialog;
import android.app.TimePickerDialog;
import android.content.pm.PackageManager;
import android.os.Build;
import android.os.Bundle;
import android.view.Gravity;
import android.view.ViewGroup;
import android.widget.Button;
import android.widget.CheckBox;
import android.widget.EditText;
import android.widget.LinearLayout;
import android.widget.ListView;
import android.widget.TextView;
import android.app.Activity;
import java.text.SimpleDateFormat;
import java.util.ArrayList;
import java.util.Calendar;
import java.util.Date;
import java.util.Locale;

public class MainActivity extends Activity {

    private TaskDatabaseHelper db;
    private TaskAdapter adapter;
    private ArrayList<Task> taskList;
    private ListView listView;
    private TextView emptyText;

    private final SimpleDateFormat dateFormat =
            new SimpleDateFormat("dd MMM yyyy, hh:mm a", Locale.getDefault());

    private static final int NOTIFICATION_PERMISSION_REQUEST_CODE = 1001;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);

        db = new TaskDatabaseHelper(this);

        ReminderReceiver.createNotificationChannel(this);
        requestNotificationPermissionIfNeeded();

        setupUi();

        AlarmScheduler.scheduleAll(this);
        loadTasks();
    }

    @Override
    protected void onResume() {
        super.onResume();
        loadTasks();
    }

    private void setupUi() {
        LinearLayout root = new LinearLayout(this);
        root.setOrientation(LinearLayout.VERTICAL);
        root.setPadding(dp(16), dp(16), dp(16), dp(16));
        root.setBackgroundColor(0xFFF5F5F5);

        TextView title = new TextView(this);
        title.setText("My To-Do List");
        title.setTextSize(28);
        title.setTextColor(0xFF111111);
        title.setGravity(Gravity.CENTER);
        title.setPadding(0, 0, 0, dp(12));

        Button addButton = new Button(this);
        addButton.setText("+ Add New Task");

        TextView helpText = new TextView(this);
        helpText.setText("Tap a task to edit/delete. Tick checkbox to mark completed.");
        helpText.setTextColor(0xFF666666);
        helpText.setTextSize(13);
        helpText.setPadding(0, dp(8), 0, dp(8));

        listView = new ListView(this);
        listView.setDividerHeight(1);

        emptyText = new TextView(this);
        emptyText.setText("No tasks yet. Add your first task.");
        emptyText.setTextSize(16);
        emptyText.setGravity(Gravity.CENTER);
        emptyText.setTextColor(0xFF888888);

        root.addView(
                title,
                new LinearLayout.LayoutParams(
                        ViewGroup.LayoutParams.MATCH_PARENT,
                        ViewGroup.LayoutParams.WRAP_CONTENT
                )
        );

        root.addView(
                addButton,
                new LinearLayout.LayoutParams(
                        ViewGroup.LayoutParams.MATCH_PARENT,
                        ViewGroup.LayoutParams.WRAP_CONTENT
                )
        );

        root.addView(
                helpText,
                new LinearLayout.LayoutParams(
                        ViewGroup.LayoutParams.MATCH_PARENT,
                        ViewGroup.LayoutParams.WRAP_CONTENT
                )
        );

        root.addView(
                listView,
                new LinearLayout.LayoutParams(
                        ViewGroup.LayoutParams.MATCH_PARENT,
                        0,
                        1
                )
        );

        root.addView(
                emptyText,
                new LinearLayout.LayoutParams(
                        ViewGroup.LayoutParams.MATCH_PARENT,
                        ViewGroup.LayoutParams.WRAP_CONTENT
                )
        );

        setContentView(root);

        taskList = new ArrayList<>();

        adapter = new TaskAdapter(this, taskList, (task, checked) -> {
            task.completed = checked;
            db.updateTask(task);

            if (checked) {
                AlarmScheduler.cancel(this, task.id);
            } else {
                AlarmScheduler.schedule(this, task);
            }

            loadTasks();
        });

        listView.setAdapter(adapter);

        addButton.setOnClickListener(v -> showTaskDialog(null));

        listView.setOnItemClickListener((parent, view, position, id) -> {
            Task task = adapter.getItem(position);
            showTaskDialog(task);
        });
    }

    private void loadTasks() {
        taskList = db.getAllTasks();
        adapter.updateData(taskList);

        if (taskList.isEmpty()) {
            emptyText.setVisibility(TextView.VISIBLE);
        } else {
            emptyText.setVisibility(TextView.GONE);
        }
    }

    private void showTaskDialog(Task existingTask) {
        boolean isEdit = existingTask != null;

        LinearLayout container = new LinearLayout(this);
        container.setOrientation(LinearLayout.VERTICAL);
        container.setPadding(dp(20), dp(10), dp(20), 0);

        EditText titleInput = new EditText(this);
        titleInput.setHint("Task title");

        EditText descriptionInput = new EditText(this);
        descriptionInput.setHint("Description");
        descriptionInput.setMinLines(2);

        CheckBox completedCheckBox = new CheckBox(this);
        completedCheckBox.setText("Completed");

        TextView reminderText = new TextView(this);
        reminderText.setTextSize(15);
        reminderText.setPadding(0, dp(10), 0, dp(6));

        Button pickReminderButton = new Button(this);
        pickReminderButton.setText("Choose Reminder Date and Time");

        Button clearReminderButton = new Button(this);
        clearReminderButton.setText("Clear Reminder");

        final long[] selectedDueTime = new long[1];

        Calendar calendar = Calendar.getInstance();

        if (isEdit) {
            titleInput.setText(existingTask.title);
            descriptionInput.setText(existingTask.description);
            completedCheckBox.setChecked(existingTask.completed);
            selectedDueTime[0] = existingTask.dueTime;

            if (existingTask.dueTime > 0) {
                calendar.setTimeInMillis(existingTask.dueTime);
            } else {
                calendar.add(Calendar.HOUR_OF_DAY, 1);
            }
        } else {
            selectedDueTime[0] = 0;
            calendar.add(Calendar.HOUR_OF_DAY, 1);
        }

        updateReminderLabel(reminderText, selectedDueTime[0]);

        pickReminderButton.setOnClickListener(v -> {
            DatePickerDialog datePickerDialog = new DatePickerDialog(
                    this,
                    (datePicker, year, month, dayOfMonth) -> {
                        calendar.set(Calendar.YEAR, year);
                        calendar.set(Calendar.MONTH, month);
                        calendar.set(Calendar.DAY_OF_MONTH, dayOfMonth);

                        TimePickerDialog timePickerDialog = new TimePickerDialog(
                                this,
                                (timePicker, hourOfDay, minute) -> {
                                    calendar.set(Calendar.HOUR_OF_DAY, hourOfDay);
                                    calendar.set(Calendar.MINUTE, minute);
                                    calendar.set(Calendar.SECOND, 0);
                                    calendar.set(Calendar.MILLISECOND, 0);

                                    selectedDueTime[0] = calendar.getTimeInMillis();
                                    updateReminderLabel(reminderText, selectedDueTime[0]);
                                },
                                calendar.get(Calendar.HOUR_OF_DAY),
                                calendar.get(Calendar.MINUTE),
                                false
                        );

                        timePickerDialog.show();
                    },
                    calendar.get(Calendar.YEAR),
                    calendar.get(Calendar.MONTH),
                    calendar.get(Calendar.DAY_OF_MONTH)
            );

            datePickerDialog.show();
        });

        clearReminderButton.setOnClickListener(v -> {
            selectedDueTime[0] = 0;
            updateReminderLabel(reminderText, selectedDueTime[0]);
        });

        container.addView(titleInput);
        container.addView(descriptionInput);
        container.addView(completedCheckBox);
        container.addView(reminderText);
        container.addView(pickReminderButton);
        container.addView(clearReminderButton);

        AlertDialog.Builder builder = new AlertDialog.Builder(this)
                .setTitle(isEdit ? "Update Task" : "Add Task")
                .setView(container)
                .setPositiveButton("Save", null)
                .setNegativeButton("Cancel", null);

        if (isEdit) {
            builder.setNeutralButton("Delete", (dialog, which) -> confirmDelete(existingTask));
        }

        AlertDialog dialog = builder.create();

        dialog.setOnShowListener(d -> {
            dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v -> {
                String title = titleInput.getText().toString().trim();
                String description = descriptionInput.getText().toString().trim();

                if (title.isEmpty()) {
                    titleInput.setError("Title is required");
                    return;
                }

                Task task;

                if (isEdit) {
                    task = existingTask;
                } else {
                    task = new Task();
                }

                task.title = title;
                task.description = description;
                task.dueTime = selectedDueTime[0];
                task.completed = completedCheckBox.isChecked();

                if (isEdit) {
                    db.updateTask(task);
                } else {
                    db.insertTask(task);
                }

                if (task.completed || task.dueTime == 0) {
                    AlarmScheduler.cancel(this, task.id);
                } else {
                    AlarmScheduler.schedule(this, task);
                }

                loadTasks();
                dialog.dismiss();
            });
        });

        dialog.show();
    }

    private void confirmDelete(Task task) {
        new AlertDialog.Builder(this)
                .setTitle("Delete Task")
                .setMessage("Are you sure you want to delete this task?")
                .setPositiveButton("Delete", (dialog, which) -> {
                    db.deleteTask(task.id);
                    AlarmScheduler.cancel(this, task.id);
                    loadTasks();
                })
                .setNegativeButton("Cancel", null)
                .show();
    }

    private void updateReminderLabel(TextView label, long dueTime) {
        if (dueTime <= 0) {
            label.setText("Reminder: None");
            label.setTextColor(0xFF888888);
        } else {
            label.setText("Reminder: " + dateFormat.format(new Date(dueTime)));
            label.setTextColor(0xFF1976D2);
        }
    }

    private void requestNotificationPermissionIfNeeded() {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
            if (checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)
                    != PackageManager.PERMISSION_GRANTED) {

                requestPermissions(
                        new String[]{Manifest.permission.POST_NOTIFICATIONS},
                        NOTIFICATION_PERMISSION_REQUEST_CODE
                );
            }
        }
    }

    private int dp(int value) {
        return (int) (value * getResources().getDisplayMetrics().density);
    }
}
